 74→  // is at most this many Unicode code points. The form refuses locally before any
 75→  // request and leaves every control exactly as the party left it.
 76→  var MAX_INTAKE_ANSWER_CODE_POINTS = 2000;
 77→  var INTAKE_ANSWER_TOO_LONG = "Intake answers must be at most 2000 characters.";
