104→  function element(tag, className, text) {
105→    var node = document.createElement(tag);
106→    if (className) {
107→      node.className = className;
108→    }
109→    if (text !== undefined && text !== null) {
110→      node.textContent = String(text);
111→    }
112→    return node;
