135→  // Unicode code points, not UTF-16 code units: an astral character (an emoji) is
136→  // one character to the server and must be one here too.
137→  function codePointCount(text) {
138→    var count = 0;
139→    for (var i = 0; i < text.length; i += 1) {
140→      var code = text.charCodeAt(i);
141→      if (code >= 0xD800 && code <= 0xDBFF && i + 1 < text.length) {
142→        var next = text.charCodeAt(i + 1);
143→        if (next >= 0xDC00 && next <= 0xDFFF) {
144→          i += 1;
145→        }
146→      }
147→      count += 1;
148→    }
149→    return count;
150→  }
