152→  function request(method, path, body) {
153→    var options = { method: method };
154→    if (body !== undefined) {
155→      options.headers = { "Content-Type": "application/json" };
156→      options.body = JSON.stringify(body);
157→    }
158→    return fetch(path, options).then(function (response) {
159→      return response.json().then(function (payload) {
160→        if (!response.ok) {
161→          var reason = payload && payload.error ? payload.error : "Something went wrong. Please try again.";
162→          throw new Error(reason);
163→        }
164→        return payload;
165→      });
166→    });
167→  }
