172→  // missing marker is the original rider shell; any other explicit value refuses
173→  // the whole page. This is demo copy selection, not authentication: the role is
174→  // never read from the URL, the document body or the fixed driver account.
175→  var formSteps = document.getElementById("form-steps");
176→  var role = formSteps.getAttribute("data-filed-by");
