199→      document.getElementById("category-next").disabled = false;
200→      // Changing the category resets everything downstream (R3 page side): the trip
201→      // list belongs to the category, so a trip picked for one category must never
202→      // survive a switch to another, and neither must any answer (W20) — the shared
203→      // safety question included. The epoch bump abandons any in-flight load.
204→      tripRequestEpoch += 1;
205→      state.tripId = null;
206→      rememberedTripId = null;
207→      questionsKey = null;
208→      while (questionList.firstChild) {
209→        questionList.removeChild(questionList.firstChild);
210→      }
211→      while (tripOptions.firstChild) {
212→        tripOptions.removeChild(tripOptions.firstChild);
213→      }
214→      document.getElementById("trip-next").disabled = true;
215→      clearError("trip-error");
216→      clearError("details-error");
217→      hide(stepTrip);
218→      hide(stepDetails);
219→    });
220→    categoryOptions.appendChild(card);
