231→  // ------------------------------------------------------------- step two
232→
233→  // W30: bring the whole trip card on screen once the list has rendered. The card
234→  // is at most one screen tall, so aligning its top shows the Continue/Back bar
235→  // too. A response that arrives after the party pressed Back must not move the
236→  // page, so a hidden trip step is left alone.
237→  function landTripCard() {
238→    if (stepTrip.hidden) {
239→      return;
240→    }
241→    stepTrip.scrollIntoView({ block: "start" });
242→  }
243→
244→  function loadTrips() {
245→    var epoch = ++tripRequestEpoch;
246→    // W20: the trip picked before this reload is remembered so the rendered list can
247→    // restore it — Back from the details step must not lose the party's selection,
248→    // even when an earlier attempt failed or its list omitted the trip.
249→    var wanted = rememberedTripId;
250→    clearError("trip-error");
251→    var boxes = tripOptions;
252→    while (boxes.firstChild) {
253→      boxes.removeChild(boxes.firstChild);
254→    }
255→    state.tripId = null;
256→    document.getElementById("trip-next").disabled = true;
257→    boxes.appendChild(element("p", "loading", "Loading trips…"));
258→    request("GET", "/api/trips?category=" + encodeURIComponent(state.category))
259→      .then(function (payload) {
260→        if (epoch !== tripRequestEpoch) {
261→          return;
262→        }
263→        while (boxes.firstChild) {
264→          boxes.removeChild(boxes.firstChild);
265→        }
266→        state.trips = Array.isArray(payload.trips) ? payload.trips : [];
267→        if (state.trips.length === 0) {
268→          boxes.appendChild(element("p", "hint", "No trips are available in the sample dataset."));
269→          landTripCard();
270→          return;
271→        }
272→        state.trips.forEach(function (trip) {
273→          var meta = [trip.date, trip.kind_label].filter(Boolean).join(" · ");
274→          var lines = [
275→            element("strong", null, trip.label),
276→            element("span", "trip-meta", meta)
277→          ];
278→          var charge = "";
279→          if (trip.fare_sgd !== null && trip.fare_sgd !== undefined) {
280→            charge = " · SGD " + Number(trip.fare_sgd).toFixed(2)
281→              + (trip.charge_label ? " " + trip.charge_label : "");
282→          }
283→          var detail = element("span", "trip-meta", "");
284→          detail.textContent = "Trip " + trip.trip_id + charge;
285→          var card = element("button", "option-card trip-card");
286→          card.type = "button";
287→          lines.forEach(function (line) { card.appendChild(line); });
288→          card.appendChild(detail);
289→          card.addEventListener("click", function () {
290→            // W20: a different trip invalidates the answers on the details step; the
291→            // same trip (a re-click after Back) keeps them.
292→            if (questionsKey && questionsKey.tripId !== trip.trip_id) {
293→              questionsKey = null;
294→              while (questionList.firstChild) {
295→                questionList.removeChild(questionList.firstChild);
296→              }
297→            }
298→            state.tripId = trip.trip_id;
299→            rememberedTripId = trip.trip_id;
300→            Array.prototype.forEach.call(boxes.children, function (child) {
301→              child.classList.remove("selected");
302→            });
303→            card.classList.add("selected");
304→            document.getElementById("trip-next").disabled = false;
305→          });
306→          // W20: restore the selection the party already made when this reload's list
307→          // still carries that trip. A list without it leaves the step unselected.
308→          if (wanted !== null && trip.trip_id === wanted) {
309→            state.tripId = wanted;
310→            card.classList.add("selected");
311→            document.getElementById("trip-next").disabled = false;
312→          }
313→          boxes.appendChild(card);
314→        });
315→        landTripCard();
316→      })
317→      .catch(function (error) {
318→        if (epoch !== tripRequestEpoch) {
319→          return;
320→        }
321→        while (boxes.firstChild) {
322→          boxes.removeChild(boxes.firstChild);
323→        }
324→        showError("trip-error", error.message);
325→        landTripCard();
326→      });
327→  }
