329→  document.getElementById("trip-back").addEventListener("click", function () {
330→    // Back invalidates an outstanding load immediately: no new request has to
331→    // start for a late response to be stale.
332→    tripRequestEpoch += 1;
333→    show(stepCategory);
334→    hide(stepTrip);
335→    stepCategory.scrollIntoView({ block: "start" });
336→  });
