338→  document.getElementById("trip-next").addEventListener("click", function () {
339→    clearError("trip-error");
340→    hide(stepTrip);
341→    // W20: rebuild the questions only when the category or the trip changed; the
342→    // unchanged pair keeps the draft the party already typed.
343→    if (!questionsKey || questionsKey.category !== state.category
344→        || questionsKey.tripId !== state.tripId) {
345→      buildQuestions();
346→      questionsKey = { category: state.category, tripId: state.tripId };
347→    }
348→    show(stepDetails);
349→    window.scrollTo(0, 0);
