354→  function buildChoiceQuestion(question) {
355→    var field = element("div", "field");
356→    var label = element("label", null, question.label);
357→    // The choices container is a div, so a <label for> cannot point at it. The
358→    // question text reaches assistive tech via role="group" + aria-labelledby.
359→    label.id = "label-" + question.key;
360→    var choices = element("div", "choice-options");
361→    choices.id = "answer-" + question.key;
362→    choices.role = "group";
363→    choices.setAttribute("aria-labelledby", "label-" + question.key);
364→    var elaborate = element("textarea", "answer-input elaborate");
365→    elaborate.rows = 2;
366→    elaborate.setAttribute("data-elaborate-for", question.key);
367→    elaborate.placeholder = "Tell us more (optional)";
368→    elaborate.setAttribute("aria-label", "Tell us more: " + question.label);
369→    elaborate.hidden = true;
370→
371→    ["Yes", "No"].forEach(function (choice) {
372→      var button = element("button", "choice-button", choice);
373→      button.type = "button";
374→      button.setAttribute("data-choice", choice);
375→      button.setAttribute("aria-pressed", "false");
376→      button.dataset.questionKey = question.key;
377→      button.addEventListener("click", function () {
378→        if (!button.classList.contains("selected")) {
379→          elaborate.value = "";
380→        }
381→        Array.prototype.forEach.call(choices.children, function (sibling) {
382→          sibling.classList.remove("selected");
383→          sibling.setAttribute("aria-pressed", "false");
384→        });
385→        button.classList.add("selected");
386→        button.setAttribute("aria-pressed", "true");
387→        show(elaborate);
388→      });
389→      choices.appendChild(button);
390→    });
391→
392→    field.appendChild(label);
393→    field.appendChild(choices);
394→    field.appendChild(elaborate);
395→    return field;
396→  }
397→
398→  function buildQuestions() {
399→    while (questionList.firstChild) {
400→      questionList.removeChild(questionList.firstChild);
401→    }
402→    var questions = QUESTIONNAIRES[state.category] || [];
403→    questions.forEach(function (question) {
404→      if (question.kind === "yes_no") {
405→        questionList.appendChild(buildChoiceQuestion(question));
406→      } else if (question.kind === "open") {
407→        var field = element("div", "field");
408→        var label = element("label", null, question.label);
409→        label.htmlFor = "answer-" + question.key;
410→        var input = element("textarea", "answer-input");
411→        input.id = "answer-" + question.key;
412→        input.rows = 2;
413→        input.dataset.questionKey = question.key;
414→        field.appendChild(label);
415→        field.appendChild(input);
416→        questionList.appendChild(field);
417→      }
418→    });
419→  }
