427→  document.getElementById("details-form").addEventListener("submit", function (event) {
428→    event.preventDefault();
429→    clearError("details-error");
430→    var description = document.getElementById("description").value;
431→    if (!description.trim()) {
432→      showError("details-error", "Please tell us what happened before sending.");
433→      return;
434→    }
435→    var amountText = document.getElementById("claim-amount").value.trim();
436→    var amount = null;
437→    if (amountText !== "") {
438→      amount = Number(amountText);
439→      if (!isFinite(amount) || amount < 0 || amount > 500) {
440→        showError("details-error", "The amount must be between 0 and 500 SGD.");
441→        return;
442→      }
443→    }
444→    var answers = {};
445→    (QUESTIONNAIRES[state.category] || []).forEach(function (question) {
446→      if (question.kind === "yes_no") {
447→        var selected = questionList.querySelector(
448→          '.choice-button.selected[data-question-key="' + question.key + '"]'
449→        );
450→        var elaborate = questionList.querySelector(
451→          'textarea[data-elaborate-for="' + question.key + '"]'
452→        );
453→        var choice = selected ? selected.dataset.choice : "";
454→        var elaboration = elaborate ? elaborate.value.trim() : "";
455→        answers[question.key] = choice
456→          ? (elaboration ? choice + " - " + elaboration : choice)
457→          : "";
458→      } else if (question.kind === "open") {
459→        var input = questionList.querySelector(
460→          'textarea[data-question-key="' + question.key + '"]'
461→        );
462→        answers[question.key] = input ? input.value : "";
463→      }
464→    });
465→
466→    // W20: the cap counts the complete serialized answer — choice, delimiter and
467→    // trimmed explanation together — in Unicode code points. Nothing is truncated
468→    // and nothing is sent: the party keeps every character they typed.
469→    var tooLong = Object.keys(answers).some(function (key) {
470→      return codePointCount(answers[key]) > MAX_INTAKE_ANSWER_CODE_POINTS;
471→    });
472→    if (tooLong) {
473→      showError("details-error", INTAKE_ANSWER_TOO_LONG);
474→      return;
475→    }
476→
477→    var submit = document.getElementById("details-submit");
478→    submit.disabled = true;
479→    request("POST", "/api/disputes", {
480→      category: state.category,
481→      filed_by: role,
482→      trip_id: state.tripId,
483→      description: description,
484→      claim_amount_sgd: amount,
485→      answers: answers
486→    })
487→      .then(function (view) {
488→        renderOutcome(view);
489→      })
490→      .catch(function (error) {
491→        submit.disabled = false;
492→        showError("details-error", error.message);
493→      });
494→  });
