498→  function renderOutcome(view) {
499→    hide(document.getElementById("form-steps"));
500→    show(outcomePanel);
501→    state.runId = view.run_id;
502→    outcomeTitle.textContent = STATUS_HEADINGS[view.status] || "Your dispute has been received";
503→    outcomeReference.textContent = view.dispute_id;
504→    outcomeMessage.textContent = view.message;
505→    hide(outcomeStatus);
506→    buildAnswerBoxes(view);
507→    window.scrollTo(0, 0);
508→  }
509→
510→  function buildAnswerBoxes(view) {
511→    while (questionBoxes.firstChild) {
512→      questionBoxes.removeChild(questionBoxes.firstChild);
513→    }
514→    var questions = Array.isArray(view.questions) ? view.questions : [];
515→    if (view.status !== "needs_info" || questions.length === 0) {
516→      hide(outcomeQuestions);
517→      return;
518→    }
519→    show(outcomeQuestions);
520→    questions.forEach(function (question, index) {
521→      var field = element("div", "field");
522→      var label = element("label", null, question);
523→      label.htmlFor = "reply-" + index;
524→      var input = element("textarea", "answer-input");
525→      input.id = "reply-" + index;
526→      input.rows = 2;
527→      // A round-two question the party has nothing to add to still needs an answer:
528→      // one click fills this box with the same sentence the run harness uses, so the
529→      // form can be completed without the party inventing words.
530→      var nothingMore = element("button", "nothing-more", "I have nothing more to add");
531→      nothingMore.type = "button";
532→      nothingMore.addEventListener("click", function () {
533→        input.value = "I have nothing more to add";
534→      });
535→      field.appendChild(label);
536→      field.appendChild(input);
537→      field.appendChild(nothingMore);
538→      questionBoxes.appendChild(field);
539→    });
540→  }
541→
542→  document.getElementById("answers-submit").addEventListener("click", function () {
543→    clearError("answers-error");
544→    var replies = [];
545→    var complete = true;
546→    Array.prototype.forEach.call(questionBoxes.querySelectorAll("textarea"), function (input) {
547→      var label = questionBoxes.querySelector('label[for="' + input.id + '"]');
548→      replies.push({ question: label ? label.textContent : "", answer: input.value });
549→      if (!input.value.trim()) {
550→        complete = false;
551→      }
552→    });
553→    if (!complete) {
554→      showError("answers-error", "Please answer each question before sending.");
555→      return;
556→    }
557→    var submit = document.getElementById("answers-submit");
558→    submit.disabled = true;
559→    outcomeStatus.textContent = "Sending your answers…";
560→    show(outcomeStatus);
561→    request("POST", "/api/disputes/" + encodeURIComponent(state.runId) + "/answers", {
562→      answers: replies
563→    })
564→      .then(function (view) {
565→        renderOutcome(view);
566→      })
567→      .catch(function (error) {
568→        submit.disabled = false;
569→        hide(outcomeStatus);
570→        showError("answers-error", error.message);
571→      });
572→  });
573→}());
