  1→/* W35 lane P, real browser: the status page keeps its header and the "Look up a reference
  2→ * number" box in place while only "My disputes" scrolls, on a screen at least 654px tall;
  3→ * below that the page scrolls normally.
  4→ *
  5→ * Run (parent-owned):
  6→ *   PUPPETEER_MODULE=... BROWSER_EXECUTABLE=... node tests/browser/w35_P_status.cjs BASE_URL OUTPUT_JSON
  7→ * BASE_URL is a mock server on the tree under test. Off-loopback requests are aborted. The
  8→ * account list and the two lookups are answered by this script with explicit fixtures, so
  9→ * the list is long enough to scroll on every screen.
 10→ */
 11→const assert = require('node:assert/strict');
 12→const fs = require('node:fs'), path = require('node:path');
 13→const puppeteer = require(process.env.PUPPETEER_MODULE || 'puppeteer');
 14→const [base, output] = process.argv.slice(2);
 15→fs.mkdirSync(path.dirname(output), {recursive: true});
 16→
 17→const THRESHOLD = 654;
 18→const DISPUTES = Array.from({length: 8}, (_, i) => ({run_id: 'w35-run-' + i, dispute_id: 'PF-W35LIST' + i,
 19→  status: 'decided', message: 'Fixture decision ' + i + ': no action. This sentence is long enough to wrap on a phone, as real messages do.', questions: []}));
 20→const TALL = {run_id: 'w35-tall', dispute_id: 'PF-W35TALL', status: 'needs_info',
 21→  message: 'We need a little more information about this trip.',
 22→  questions: ['Fixture question one?', 'Fixture question two?', 'Fixture question three?', 'Fixture question four?',
 23→    'Fixture question five?', 'Fixture question six?']};
 24→const SHORT = {run_id: 'w35-short', dispute_id: 'PF-W35SHORT', status: 'under_review', message: 'Under review.', questions: []};
 25→// Threshold-1/threshold/threshold+1 on the 320px phone whose bar wraps to two rows (the
 26→// width that sets the threshold) and on a desktop, the required phone and desktop sizes,
 27→// a 390x700 phone (framed), and short desktop/landscape panes (page scroll).
 28→const SIZES = [[320, 653], [320, 654], [320, 655], [1280, 653], [1280, 654], [1280, 655],
 29→  [360, 740], [320, 740], [390, 844], [600, 900], [1280, 844], [1200, 600], [740, 360], [390, 700]];
 30→const report = {passed: false, views: [], errors: []};
 31→
 32→(async () => {
 33→  const browser = await puppeteer.launch({headless: true, executablePath: process.env.BROWSER_EXECUTABLE, args: ['--no-sandbox']});
 34→  const open = async (width, height, hash = '') => {
 35→    const page = await browser.newPage();
 36→    page.on('pageerror', e => report.errors.push(`${width}x${height}: ${e.message}`));
 37→    await page.setViewport({width, height});
 38→    await page.setRequestInterception(true);
 39→    page.on('request', r => {
 40→      const u = new URL(r.url());
 41→      if (u.hostname !== '127.0.0.1') return r.abort();
 42→      const json = body => r.respond({status: 200, contentType: 'application/json', body: JSON.stringify(body)});
 43→      if (u.pathname === '/api/demo/rider') return json({account: {kind: 'rider', label: 'Demo account'}, disputes: DISPUTES});
 44→      if (u.pathname === '/api/disputes/PF-W35TALL') return json(TALL);
 45→      if (u.pathname === '/api/disputes/PF-W35SHORT') return json(SHORT);
 46→      return r.continue();
