 49→    await page.waitForFunction(n => document.querySelectorAll('#account-list > .step').length === n, {}, DISPUTES.length);
 50→    assert.equal(await page.evaluate(() => !!document.querySelector('.status-shell') && !!document.querySelector('.status-lookup') && !!document.querySelector('.status-list')),
 51→      true, 'status page has its shell, fixed lookup box and internal-list region');
 52→    return page;
 53→  };
 54→  const geometry = page => page.evaluate(() => {
 55→    const rect = e => { const r = e.getBoundingClientRect(); return {top: r.top, bottom: r.bottom, left: r.left, right: r.right, height: r.height}; };
 56→    const list = document.getElementById('account-list'), result = document.getElementById('lookup-result');
 57→    const cards = list.querySelectorAll(':scope > .step');
 58→    return {vh: innerHeight, scrollY, docHeight: document.documentElement.scrollHeight,
 59→      overflow: document.documentElement.scrollWidth - innerWidth,
 60→      bodyOverflow: getComputedStyle(document.body).overflow,
 61→      bar: rect(document.querySelector('nav.switch-bar')), barShown: getComputedStyle(document.querySelector('nav.switch-bar')).display !== 'none',
 62→      header: rect(document.querySelector('.party-header')), lookup: rect(document.querySelector('.status-lookup')),
 63→      input: rect(document.getElementById('reference-input')), check: rect(document.getElementById('reference-check')),
 64→      section: rect(document.querySelector('.status-list')), list: rect(list),
 65→      listClient: list.clientHeight, listFull: list.scrollHeight, listTop: list.scrollTop,
 66→      lastCard: rect(cards[cards.length - 1]),
 67→      result: rect(result), resultClient: result.clientHeight, resultFull: result.scrollHeight};
 68→  });
