106→        await page.focus('#reference-check');
107→        await page.keyboard.press('Tab');
108→        assert.equal(await page.evaluate(() => document.activeElement.id), 'account-list', 'Tab from Check status reaches the list region');
109→        await page.keyboard.press('End');
110→        await page.waitForFunction(() => document.getElementById('account-list').scrollTop > 0, {timeout: 5000});
111→        g = await geometry(page);
112→        view.checks.push({stage: 'keyboard', ...g});
113→        assert.deepEqual({header: g.header, lookup: g.lookup}, before, 'keyboard scrolling moves only the list');
114→        assert.equal(g.scrollY, 0);
115→        await page.evaluate(() => { document.getElementById('account-list').scrollTop = 0; document.activeElement.blur(); });
