117→        assert.notEqual(g.bodyOverflow, 'hidden', 'a short screen scrolls the page');
118→        assert.ok(g.listFull <= g.listClient + 1, 'the list is not its own scroller on a short screen');
119→        assert.ok(g.docHeight > g.vh, 'fixture: the page is taller than the screen');
