121→        g = await geometry(page);
122→        view.checks.push({stage: 'page-end', ...g});
123→        assert.ok(g.scrollY > 0, 'the page scrolls');
124→        assert.ok(g.lastCard.bottom <= g.vh + 1, 'the last dispute is reachable');
125→        await page.evaluate(() => window.scrollTo(0, 0));
