127→      // A short lookup result shows whole; a tall one scrolls inside the lookup box.
128→      for (const [ref, tall] of [['PF-W35SHORT', false], ['PF-W35TALL', true]]) {
129→        await page.$eval('#reference-input', (e, v) => { e.value = v; }, ref);
