  1→/* W35 lane P, real browser: WCAG AA text contrast measured from COMPUTED colours on the five
  2→ * party/start pages, in the states a party actually sees, at a phone and a desktop width.
  3→ *
  4→ * Run (parent-owned):
  5→ *   PUPPETEER_MODULE=... BROWSER_EXECUTABLE=... node tests/browser/w35_P_contrast.cjs BASE_URL OUTPUT_JSON
  6→ * Off-loopback requests are aborted. Lists, lookups and the dispute POST are answered with
  7→ * explicit fixtures.
  8→ *
  9→ * Every element with its own visible text is measured: its colour against the background
 10→ * actually painted behind it (ancestor backgrounds composited, opacity applied), and each
 11→ * input placeholder. Small text needs 4.5:1, large text (24px, or 18.66px at weight 700+)
 12→ * 3:1. Text inside a DISABLED control is reported but exempt (WCAG 1.4.3 "inactive user
 13→ * interface component"). The full table goes to OUTPUT_JSON.
 14→ */
 15→const assert = require('node:assert/strict');
 16→const fs = require('node:fs'), path = require('node:path');
 17→const puppeteer = require(process.env.PUPPETEER_MODULE || 'puppeteer');
 18→const [base, output] = process.argv.slice(2);
 19→fs.mkdirSync(path.dirname(output), {recursive: true});
 20→
 21→const DISPUTES = [
 22→  {run_id: 'c1', dispute_id: 'PF-W35C1', status: 'decided', message: 'Fixture decision: no action.', questions: []},
 23→  {run_id: 'c2', dispute_id: 'PF-W35C2', status: 'needs_info', message: 'We need a little more information.', questions: ['Fixture question?']},
 24→];
 25→const LOOKUP = {run_id: 'c3', dispute_id: 'PF-W35C3', status: 'under_review', message: 'Under review.', questions: []};
 26→const REFUSAL = 'Fixture refusal: please try again.';
 27→const report = {passed: false, states: [], failures: [], errors: []};
 28→
 29→const MEASURE = () => {
 30→  const parse = c => { const m = c.match(/rgba?\(([^)]+)\)/); if (!m) return [0, 0, 0, 0];
 31→    const p = m[1].split(/[ ,/]+/).filter(Boolean).map(Number); return [p[0], p[1], p[2], p.length > 3 ? p[3] : 1]; };
 32→  const over = (top, bottom) => { const a = top[3]; return [0, 1, 2].map(i => top[i] * a + bottom[i] * (1 - a)).concat(1); };
 33→  const lum = c => { const l = c.slice(0, 3).map(v => { v /= 255; return v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); });
 34→    return 0.2126 * l[0] + 0.7152 * l[1] + 0.0722 * l[2]; };
 35→  const ratio = (a, b) => { const x = lum(a), y = lum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
 36→  const hex = c => '#' + c.slice(0, 3).map(v => Math.round(v).toString(16).padStart(2, '0')).join('');
 37→  // The colour painted behind el: walk to the root, then composite downwards.
 38→  const backdrop = el => {
 39→    const chain = [];
 40→    for (let n = el; n; n = n.parentElement) chain.push(n);
 41→    let bg = [255, 255, 255, 1];
 42→    for (const n of chain.reverse()) {
 43→      const s = getComputedStyle(n), c = parse(s.backgroundColor), o = Number(s.opacity);
 44→      bg = over([c[0], c[1], c[2], c[3] * o], bg);
 45→    }
 46→    return bg;
 47→  };
 48→  const opacity = el => { let o = 1; for (let n = el; n; n = n.parentElement) o *= Number(getComputedStyle(n).opacity); return o; };
 49→  const visible = el => { const r = el.getBoundingClientRect(), s = getComputedStyle(el);
 50→    return r.width > 0 && r.height > 0 && s.visibility === 'visible' && !el.closest('[hidden]') && !el.closest('[aria-hidden="true"]'); };
 51→  const rows = [];
 52→  const record = (el, fgRaw, what) => {
 53→    const s = getComputedStyle(el), size = parseFloat(s.fontSize), weight = Number(s.fontWeight);
 54→    const bg = backdrop(el.parentElement || el);
 55→    const own = parse(s.backgroundColor);
 56→    const behind = over([own[0], own[1], own[2], own[3] * Number(s.opacity)], bg);
 57→    const fg = over([fgRaw[0], fgRaw[1], fgRaw[2], fgRaw[3] * opacity(el)], behind);
 58→    const large = size >= 24 || (size >= 18.66 && weight >= 700);
 59→    const disabled = !!el.closest('button:disabled, input:disabled, textarea:disabled');
 60→    rows.push({what, text: (what === 'placeholder' ? el.placeholder : el.textContent).trim().replace(/\s+/g, ' ').slice(0, 60),
 61→      tag: el.tagName.toLowerCase(), cls: el.className && typeof el.className === 'string' ? el.className : '', id: el.id,
 62→      fg: hex(fg), bg: hex(behind), size, weight, large, disabled, ratio: Math.round(ratio(fg, behind) * 100) / 100,
 63→      need: large ? 3 : 4.5});
 64→  };
 65→  for (const el of document.querySelectorAll('body *')) {
 66→    if (!visible(el)) continue;
 67→    const ownText = [...el.childNodes].some(n => n.nodeType === 3 && n.textContent.trim());
 68→    if (ownText) record(el, parse(getComputedStyle(el).color), 'text');
 69→    if ((el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') && el.placeholder && !el.value) {
 70→      record(el, parse(getComputedStyle(el, '::placeholder').color), 'placeholder');
 71→    }
 72→  }
 73→  return rows;
 74→};
 75→
 76→(async () => {
 77→  const browser = await puppeteer.launch({headless: true, executablePath: process.env.BROWSER_EXECUTABLE, args: ['--no-sandbox']});
 78→  const open = async (url, width) => {
 79→    const page = await browser.newPage();
 80→    page.on('pageerror', e => report.errors.push(`${width} ${url}: ${e.message}`));
 81→    await page.setViewport({width, height: 844});
 82→    await page.setRequestInterception(true);
 83→    page.on('request', r => {
 84→      const u = new URL(r.url());
 85→      if (u.hostname !== '127.0.0.1') return r.abort();
 86→      const json = (body, status = 200) => r.respond({status, contentType: 'application/json', body: JSON.stringify(body)});
 87→      if (u.pathname === '/api/demo/rider' || u.pathname === '/api/demo/driver') return json({account: {}, disputes: DISPUTES});
 88→      if (u.pathname === '/api/disputes/PF-W35C3') return json(LOOKUP);
 89→      if (u.pathname === '/api/disputes' && r.method() === 'POST') {
 90→        return page.__refuse ? json({error: REFUSAL}, 500) : (page.__hold ? undefined : json(LOOKUP));
 91→      }
 92→      return r.continue();
 93→    });
 94→    await page.goto(base + url, {waitUntil: 'networkidle0'});
 95→    await page.mouse.move(0, 0);
 96→    return page;
 97→  };
 98→  const measure = async (page, name, width) => {
 99→    await page.mouse.move(0, 0);
100→    await new Promise(r => setTimeout(r, 250));
101→    const rows = await page.evaluate(MEASURE);
102→    report.states.push({name, width, rows});
103→    for (const row of rows) if (!row.disabled && row.ratio < row.need) report.failures.push({name, width, ...row});
104→    return rows;
105→  };
106→  const find = (rows, pred, label) => { const r = rows.find(pred); assert.ok(r, 'measured: ' + label); return r; };
107→  // Named spots: recorded (not thrown), so one run lists every low pair at once.
108→  const spot = (state, width, row, label) => {
109→    report.spots = report.spots || [];
110→    report.spots.push({state, width, label, ratio: row.ratio, fg: row.fg, bg: row.bg});
111→    if (row.ratio < 4.5) report.failures.push({name: state, width, spot: label, ...row});
112→  };
113→  try {
114→    for (const width of [390, 1280]) {
115→      let p = await open('/start/', width);
116→      let rows = await measure(p, 'start', width);
117→      spot('start eyebrow', width, find(rows, r => r.cls === 'eyebrow', 'start eyebrow'), 'start eyebrow');
118→      spot('start card title', width, find(rows, r => r.cls === 'card-title', 'start card title'), 'start card title');
119→      await p.close();
120→
121→      for (const file of ['index.html', 'driver-filing.html']) {
122→        p = await open('/party/' + file, width);
123→        rows = await measure(p, file + ' step 1', width);
124→        spot('eyebrow on tint', width, find(rows, r => r.cls === 'eyebrow', 'eyebrow on tint'), 'eyebrow on tint');
125→        spot('bar pill', width, find(rows, r => r.text === 'File a dispute' && r.tag === 'a', 'bar pill'), 'bar pill');
126→        spot('step number', width, find(rows, r => r.cls === 'step-number', 'step number'), 'step number');
127→        await p.click('#category-options .option-card');
128→        rows = await measure(p, file + ' step 1 chosen', width);
129→        spot('enabled Continue', width, find(rows, r => r.id === 'category-next' && !r.disabled, 'enabled Continue'), 'enabled Continue');
130→        await p.click('#category-next');
131→        await p.waitForSelector('#trip-options .trip-card');
132→        await p.evaluate(() => document.querySelector('#trip-options .trip-card').click());
133→        await measure(p, file + ' step 2 chosen', width);
134→        await p.click('#trip-next');
135→        rows = await measure(p, file + ' step 3', width);
136→        spot('summary label', width, find(rows, r => r.cls === 'filing-summary-label', 'summary label'), 'summary label');
137→        spot('Send', width, find(rows, r => r.id === 'details-submit', 'Send'), 'Send');
138→        await p.$eval('#description', e => { e.value = 'Contrast fixture'; });
139→        p.__hold = true;
140→        await p.click('#details-submit');
141→        await p.waitForFunction(() => document.getElementById('details-status').textContent !== '');
142→        rows = await measure(p, file + ' step 3 sending', width);
143→        spot('status line', width, find(rows, r => r.id === 'details-status', 'status line'), 'status line');
144→        await p.close();
145→        p = await open('/party/' + file, width);
146→        p.__refuse = true;
147→        await p.click('#category-options .option-card');
148→        await p.click('#category-next');
149→        await p.waitForSelector('#trip-options .trip-card');
150→        await p.evaluate(() => document.querySelector('#trip-options .trip-card').click());
151→        await p.click('#trip-next');
152→        await p.$eval('#description', e => { e.value = 'Contrast fixture'; });
153→        await p.click('#details-submit');
154→        await p.waitForSelector('#details-error:not([hidden])');
155→        rows = await measure(p, file + ' step 3 refused', width);
156→        spot('error', width, find(rows, r => r.id === 'details-error', 'error'), 'error');
157→        p.__refuse = false;
158→        await p.click('#details-submit');
159→        await p.waitForSelector('#outcome:not([hidden])');
160→        await measure(p, file + ' outcome', width);
161→        await p.close();
162→      }
163→
164→      p = await open('/party/status.html', width);
165→      await p.click('#reference-check');
166→      await p.waitForSelector('#reference-error:not([hidden])');
167→      await measure(p, 'status empty lookup', width);
168→      await p.$eval('#reference-input', e => { e.value = 'PF-W35C3'; });
169→      await p.click('#reference-check');
170→      await p.waitForSelector('#lookup-result .step');
171→      await measure(p, 'status with result', width);
172→      await p.close();
173→      p = await open('/party/driver.html', width);
174→      await measure(p, 'driver account', width);
175→      await p.close();
176→    }
177→    report.passed = report.failures.length === 0 && report.errors.length === 0;
178→  } catch (e) {
179→    report.error = String(e && e.stack || e);
180→  } finally {
181→    await browser.close();
182→    // The distinct colour pairs, for the report.
183→    const pairs = {};
184→    for (const s of report.states) for (const r of s.rows) {
185→      const key = [r.fg, r.bg, r.large ? 'large' : 'small', r.disabled ? 'disabled' : 'enabled'].join(' ');
186→      pairs[key] = pairs[key] || {fg: r.fg, bg: r.bg, large: r.large, disabled: r.disabled, ratio: r.ratio, need: r.need, examples: []};
187→      if (pairs[key].examples.length < 3) pairs[key].examples.push(`${s.name}@${s.width}: ${r.text}`);
188→    }
189→    report.pairs = Object.values(pairs).sort((a, b) => a.ratio - b.ratio);
190→    if (report.error) report.passed = false;
191→    fs.writeFileSync(output, JSON.stringify(report, null, 2));
192→    console.log(JSON.stringify({passed: report.passed, states: report.states.length, pairs: report.pairs.length,
193→      failures: report.failures.length, error: report.error}));
194→    for (const f of report.failures.slice(0, 20)) console.log('LOW', f.ratio, f.fg, 'on', f.bg, f.name + '@' + f.width, JSON.stringify(f.text));
195→    process.exitCode = report.passed ? 0 : 1;
196→  }
197→})().catch(e => { console.error(e); process.exitCode = 1; });
